INSERT INTO `noticias` (`id_noticia`, `nombre`, `img_url`, `descripcion`, `info`, `fecha`, `direccion`, `filtros`, `id_usuario`, `creado_en`) VALUES
(22, 'Desde este viernes Necochea se deleitará con «La Noche de los Coros» en el Teatro Municipal', '[\"/img/noticia/22/desde-este-viernes-necochea-se-deleitara-con-la-noche-de-los_2026-06-25_1.png\"]', 'El encuentro reunirá a agrupaciones corales locales, del país y de Uruguay, en dos jornadas dedicadas a la música y el arte colectivo.', 'Durante este viernes 19 y sábado 20 de junio, el Teatro Municipal “Luis Sandrini” será el escenario de una nueva edición de la “Noche de los Coros”, un encuentro que reunirá a agrupaciones corales locales, del país y de Uruguay, en dos jornadas dedicadas a la música y el arte colectivo.\r\n\r\nEl evento se desarrollará ambos días a partir de las 20:00 horas, con acceso libre y gratuito, aunque los interesados deberán retirar las entradas previamente.\r\n\r\n«La Noche de los Coros» contará con la participación de grupos provenientes de Necochea, Mar del Plata, Miramar, Buenos Aires y Montevideo, ofreciendo al público un repertorio variado y propuestas para toda la familia.\r\n\r\nEntre las propuestas destacadas, Vocal Kingdom aportará una energía vibrante y contemporánea con clásicos del pop y rock en inglés; mientras que Mar Musical, integrados por jóvenes voces, rescatará repertorios populares y folklóricos latinoamericanos.\r\n\r\n\r\nPor su parte el Coro Covadonga, perteneciente al Centro Asturiano, ofrecerá una propuesta marcada por la tradición celta y asturiana, combinando folk con matices académicos. Coral Miramar, con más de cincuenta años de trayectoria, presentará un repertorio que equilibra lo popular y lo académico.\r\n\r\nDesde la ciudad de Buenos Aires llegará la Agrupación Coral Colegiales, reconocida por un estilo ecléctico que fusiona rock y pop nacional con arreglos originales. En tanto, el Coro Experimental de Montevideo brindará una propuesta escénica colorida y teatral, integrando la tradición del candombe con una fuerte impronta visual y artística.\r\n\r\nPara retirar las entradas, se recomienda consultar previamente al whatsapp 2262-431153 para saber sobre la disponibilidad.\r\n\r\nPROGRAMACION:\r\n\r\nViernes 19 de junio\r\n\r\nCoro Vocal Kingdon (Necochea)\r\nCoro Universitario (Mar del Plata)\r\nCoro Mar Musical (Necochea)\r\nCoro Covadonga (Necochea)\r\nAgrupación Coral Colegiales (Buenos Aires)\r\nCoro La Experimental (Montevideo)\r\n\r\nSábado 20 de junio\r\n\r\nCoro Vocal Kingdon (Necochea)\r\nCoro Universitario (Mar del Plata)\r\nCoro Mar Musical (Necochea)\r\nAgrupación Coral Miramar (Miramar)\r\nAgrupación Coral Colegiales (Buenos Aires)\r\nCoro La Experimental (Montevideo)', '2026-06-19', 'Teatro Paris', '[\"Necochea\",\"Actividades\"]', 1, '2026-06-25 11:23:01'),
(23, 'El regreso del salto hípico oficial a Necochea también fortalece el turismo durante todo el año', '[\"/img/noticia/23/el-regreso-del-salto-hipico-oficial-a-necochea-tambien-forta_2026-06-25_1.png\"]', 'El regreso de un Concurso Oficial de Salto Hípico a Necochea, luego de 25 años, no solo representó un importante acontecimiento deportivo, sino también una nueva oportunidad para seguir posicionando a', 'Organizada por el Centro Hípico La Majúa, con el acompañamiento de la Municipalidad de Necochea, a través de la Secretaría de Turismo y Desarrollo Productivo, la competencia reunió el pasado fin de semana a más de 60 binomios provenientes de Pinamar, Mar del Plata, Tandil y distintos puntos de la región, además de familiares, entrenadores y acompañantes que llegaron a la ciudad para participar del certamen.\r\n\r\nDesde la Secretaría de Turismo se destacó la importancia de respaldar este tipo de iniciativas, ya que permiten atraer visitantes en temporada baja, generando un movimiento que beneficia a distintos sectores de la economía local, como el alojamiento, la gastronomía y el comercio.\r\n\r\nEn ese marco, el secretario Matías Sierra e integrantes del área, estuvieron presentes durante el evento brindando información sobre los principales atractivos del distrito y entregando folletería turística, con el objetivo de que quienes visitaron la ciudad puedan conocer la amplia oferta de naturaleza, gastronomía, actividades recreativas y propuestas culturales que ofrece Necochea durante todo el año.\r\n\r\n\r\n\r\nEl certamen se desarrolló en las instalaciones del Centro Hípico La Majúa, ubicado en el predio de la Sociedad Rural, y marcó el retorno de la actividad oficial de la Federación Ecuestre Argentina a la ciudad, luego de que el último concurso de estas características se realizara en 2001.\r\n\r\nLa competencia contó con la participación de delegaciones del Haras La Malcriada de Pinamar, Haras Los Abuelos de Sierra de los Padres, Club Ecuestre Mar del Plata, Hípico Raíces de Tandil y Club Hípico General Pueyrredón, además de representantes locales. Entre los participantes se destacó la presencia del jinete de primera categoría Maximiliano Guadagna.\r\n\r\nLos clubes visitantes resaltaron el excelente estado de la pista, la calidad de las instalaciones y la hospitalidad recibida, mientras que el evento también tuvo una amplia difusión a nivel nacional mediante la transmisión en vivo por streaming y la cobertura del programa especializado El Mundo de los Caballos.\r\n\r\n\r\nDesde el municipio se continúa impulsando y acompañando este tipo de encuentros, entendiendo que el turismo de eventos constituye una herramienta estratégica para desestacionalizar la actividad, promover a Necochea como destino durante los doce meses del año y generar nuevas oportunidades para el desarrollo económico local.', '2026-06-18', NULL, NULL, 1, '2026-06-25 11:24:22'),
(24, 'Turismo avanza en la evaluación de los proyectos presentados en la convocatoria de subsidios', '[\"/img/noticia/24/turismo-avanza-en-la-evaluacion-de-los-proyectos-presentados_2026-06-25_1.png\"]', 'La Secretaría de Turismo y Desarrollo Productivo encabezada por Matías Sierra informa que finalizó el período de presentación de proyectos en el marco de la convocatoria destinada a promover la iguald', 'En total, se recibieron siete (7) propuestas, cuyos sobres fueron abiertos el pasado 10 de junio, conforme al cronograma establecido en las bases y condiciones del programa.\r\n\r\nActualmente, los proyectos se encuentran en etapa de evaluación por parte del jurado designado, integrado por:\r\n\r\n-Micaela Esandi, CFP N° 402.\r\n-Dra. Patricia Sureda, Coordinadora de UNICEN Quequén.\r\n-Amarylis Sánchez, Dirección Políticas y Género de la Municipalidad.\r\n-Claudia Calvo, Asociación de Hoteles y Afines de Necochea.\r\n-Isabel Génova, Dirección de Gestión Ambiental Municipal.\r\n\r\n\r\nCabe recordar que la presente iniciativa contempla una asistencia financiera total $ 4.000.000, distribuidas en dos subsidios de $ 2.000.000 cada uno. Uno de ellos está destinado a proyectos que promuevan la igualdad de género y la diversidad por lo que deberán estar presididos por mujeres, mientras que el otro financiará iniciativas vinculadas al cuidado del medio ambiente y la promoción del turismo sostenible.\r\n\r\nUna vez concluida la evaluación, se darán a conocer los proyectos seleccionados, que podrán desarrollarse durante la temporada 2026/2027, contribuyendo al fortalecimiento de una oferta turística más inclusiva, sustentable y comprometida con el desarrollo local.', '2026-06-17', NULL, NULL, 1, '2026-06-25 11:25:22'),
(25, 'La Plaza se puso en «Modo Mundial» con un intercambio de figuritas que convocó a toda la familia', '[\"/img/noticia/25/la-plaza-se-puso-en-modo-mundial-con-un-intercambio-de-figur_2026-06-25_1.png\"]', 'En la víspera del debut de la Selección Argentina, la Plaza Dardo Rocha se puso en «Modo Mundial», con un evento de intercambio de figuritas que concentró variadas actividades y atrajo a la familia ne', 'Satisfecho con el clima, que fue ideal para este tipo de actividades al aire libre, Sierra expresó que «estamos muy contentos por la cantidad de gente que vino, familias que disfrutaron este día y de una iniciativa que la habíamos pensado hace un mes atrás. El intendente (Arturo Rojas) nos dio el visto bueno para poder realizarla y estamos sorprendidos de la cantidad de gente que vino».\r\n\r\nEl funcionario no dejó de agradecer al sector privado de la ciudad, «que colaboró con todos los sorteos que se llevaron a cabo», como así «a la Dirección de Deportes que nos acompañó y a todas las dependencias municipales».\r\n\r\n\r\n\r\nEn medio del intercambio de figuritas, la música no podía faltar y en ese sentido, la Banda Municipal y la banda de Calle 85 le pusieron ritmo a la tarde. Además, en simultáneo al gazebo principal de intercambio se montaron otros sectores alternativos para que los más chicos pudieran sacarse fotos y divertirse.\r\n\r\nEn cuanto al intercambio de figuritas en sí, Sierra destacó que «atrae tanto a los grandes como a los chicos, y por eso queremos agradecer a todas las familias que se acercaron, porque en definitiva el objetivo era ese, que estén las familias disfrutando y compartiendo esta hermosa jornada, el clima nos acompañó y eso es fundamental».', '2026-06-16', NULL, NULL, 1, '2026-06-25 11:26:21'),
(26, 'Un nuevo corredor gastronómico invita a disfrutar de los mejores sabores con vistas únicas al mar y al río', '[\"/img/noticia/26/un-nuevo-corredor-gastronomico-invita-a-disfrutar-de-los-mej_2026-06-25_1.png\"]', 'La Secretaría de Turismo y Desarrollo Productivo presenta un nuevo Corredor Gastronómico de Mar y Río, una propuesta que combina la excelencia gastronómica local con algunos de los paisajes más emblem', 'El circuito está integrado por establecimientos ubicados en puntos privilegiados de la costa y la ribera, permitiendo a vecinos y visitantes disfrutar de desayunos, almuerzos, meriendas y cenas con vistas panorámicas al océano Atlántico o al río Quequén.\r\n\r\nLa iniciativa busca poner en valor la oferta gastronómica local y promover experiencias que unen naturaleza, identidad y sabores.\r\n\r\nLa promoción de corredores gastronómicos forma parte de las acciones impulsadas por la Secretaría para fortalecer la actividad turística y comercial del destino.\r\n\r\nLos establecimientos que forman parte de este recorrido son:\r\n\r\n-Parador Neptuno\r\n-La Hélice\r\n-Pipeline\r\n-Cabañas Río Quequén\r\n-Cantina El Muelle\r\n-Océano By Bruga\r\n\r\nTodos los espacios ofrecen una variada carta gastronómica para cualquiera de las cuatro comidas diarias, con propuestas pensadas para distintos gustos y preferencias.\r\n\r\nAdemás, algunos de los establecimientos cuentan con opciones de menú aptas parapersonas celíacas.\r\n\r\nQuienes deseen conocer más detalles sobre este corredor y otras propuestas turísticas pueden consultar la información disponible en la página oficial de la Secretaría de Turismo y Desarrollo Productivo www.necochea.tur.ar o a través del whatsapp 2262-431153.', '2026-06-12', NULL, NULL, 1, '2026-06-25 11:27:20'),
(27, 'El gran intercambio de figuritas llegará acompañado de variadas actividades en la Plaza Dardo Rocha', '[\"/img/noticia/27/el-gran-intercambio-de-figuritas-llegara-acompanado-de-varia_2026-06-25_1.png\"]', 'El Mundial ya se siente en Necochea, y el día anterior al debut de la Selección Argentina se prepara un gran evento para toda la familia en la plaza del centro.', 'El Mundial ya está aquí y Necochea se prepara para vivirlo a pleno. Con el inicio de la máxima cita del fútbol, la Secretaría de Turismo y Desarrollo Productivo invita a toda la comunidad y visitantes a participar de un gran intercambio de figuritas el próximo lunes 15 de junio en la Plaza Dardo Rocha, a partir de las 14 horas, en el marco de un evento para toda la familia.\r\n\r\nLa propuesta busca reunir a grandes y chicos en un espacio de pura emoción, sumando esta vez actividades especiales para palpitar la previa del debut de la Selección Argentina en el Mundial como nunca antes.\r\n\r\nActividades en el marco del intercambio de figuritas:\r\n\r\n–Gigantografías para selfies temáticas.\r\n\r\n–Pondrán ritmo a la tarde la Banda Municipal y la banda de rock Calle 85.\r\n\r\n–Sorteos de álbumes de figuritas donados por Hugo Juguetes.\r\n\r\n–Intervención artística en vivo a cargo de Amar a Morir Prendas de Diseño, quienes confeccionarán una bandera que luego será sorteada entre los presentes.\r\n\r\n–El comercio Fútbol Shop Necochea colaborará con camisetas para que todos los presentes puedan sacarse fotos y vivir la experiencia futbolera.\r\n\r\n–L’angolo Cuadros donará dos obras para sortear.\r\n\r\n\r\n\r\n\r\nDesde la Secretaría a cargo de Matías Sierra, destacaron que la convocatoria es abierta y gratuita a todo el público. “Los esperamos para compartir una jornada de intercambio donde la pasión por el Mundial, la música y la familia serán los grandes protagonistas. ¡Traé tu álbum, tus repetidas y preparate para completar tu colección antes de que ruede la pelota!”, invitaron.', '2026-06-11', NULL, NULL, 1, '2026-06-25 11:28:04'),
(28, 'Por el Día del Padre, sortearán experiencias turísticas para que visitantes de la región disfruten de Necochea', '[\"/img/noticia/28/por-el-dia-del-padre-sortearan-experiencias-turisticas-para-_2026-06-25_1.png\"]', 'Se impulsa una acción promocional con premios para visitantes que residen a más de 50 kilómetros de la ciudad y desean descubrir los atractivos naturales de Necochea.', 'La Secretaría de Turismo y Desarrollo Productivo lanzó una promoción especial en el mes en que se celebra el Día del Padre, y lanzó un sorteo exclusivo para participantes que residen a más de 50 kilómetros de Necochea, y que se realizará el viernes 12 de junio.\r\n\r\nLa iniciativa contempla el sorteo de tres vouchers con propuestas que combinan alojamiento, gastronomía y actividades culturales, gracias al acompañamiento de prestadores turísticos y gastronómicos locales que se sumaron a la acción promocional.\r\n\r\nEntre los establecimientos participantes se encuentran Mar y Cielo, Aparts del Lago, Cabañas Río Quequén, Gros, Veredón, Doppio, La Tienda y Wo Espacio Cultural.\r\n\r\n\r\n\r\nPara participar, los interesados deberán seguir la cuenta oficial de Instagram @necochetur, colocar “Me gusta” en la publicación del sorteo y etiquetar a la persona con quien compartirían la experiencia o a quien deseen regalarla.\r\n\r\nLa propuesta forma parte de las acciones de promoción impulsadas por la Secretaría para fortalecer el movimiento turístico, invitando a visitantes de la región a descubrir los atractivos naturales, gastronómicos y culturales del distrito.\r\n\r\nEl sorteo se realizará el 12 de junio y los ganadores serán anunciados a través de las redes sociales de Necochea Turismo.', '2026-06-04', NULL, NULL, 1, '2026-06-25 11:28:50'),
(29, 'Necochea se adhirió al Sello de Calidad Turística Bonaerense', '[\"/img/noticia/29/necochea-se-adhirio-al-sello-de-calidad-turistica-bonaerense_2026-06-25_1.png\"]', 'Desde la Secretaría de Turismo y Desarrollo Productivo, la propuesta fue socializada con prestadores turísticos locales a través de canales de comunicación y grupos de WhatsApp.', 'La Municipalidad de Necochea adhirió oficialmente al Sello de Calidad Turística Bonaerense (CTB), iniciativa impulsada por la Subsecretaría de Turismo de la Provincia de Buenos Aires, dependiente del Ministerio de Producción, Ciencia e Innovación Tecnológica, a través de la Resolución N° 94/2026.\r\n\r\nEl Sello CTB es una propuesta de adhesión voluntaria destinada a prestaciones turísticas de distintos rubros y tamaños, tanto del ámbito público como privado. Su objetivo es acompañar a las organizaciones en el camino de la mejora continua, promoviendo la calidad, la inclusión y la sostenibilidad, y reconociendo el compromiso de quienes trabajan por un turismo responsable.\r\n\r\n\r\n\r\nLa convocatoria estuvo dirigida a prestadores turísticos de la provincia-alojamientos, agencias, gastronomía, balnearios, termas, entre otros- que contarán con más de un/a trabajador/a, inscripción en el registro correspondiente y habilitación vigente. En este marco, cada municipio tenía la posibilidad de postular a los establecimientos interesados.\r\n\r\nDesde la Secretaría de Turismo y Desarrollo Productivo de Necochea, encabezada por Matías Sierra, la propuesta fue socializada con los prestadores turísticos locales a través de distintos canales de comunicación y grupos de WhatsApp. Aquellos establecimientos que manifestaron interés y cumplían con los requisitos establecidos fueron postulados para formar parte del programa.\r\n\r\n\r\n\r\nLas organizaciones locales postuladas fueron:\r\n\r\n-Aparts del Lago de los Cisnes\r\n-Las Barrancas Aparts&Spa\r\n-Pipeline\r\n-Complejo Monte Pasubio\r\n\r\nEn el marco de la implementación del programa, el jueves 28 de mayo se desarrolló una reunión virtual informativa de la que participaron representantes del municipio, las organizaciones postuladas y personas interesadas en conocer el proceso de aplicación y el contenido del sello.\r\n\r\nDurante el encuentro se presentaron los principales lineamientos del programa, la metodología de ejecución, los ejes temáticos, los niveles de cumplimiento, el cronograma de trabajo y las instancias de acompañamiento previstas para las organizaciones participantes.\r\n\r\nCon esta adhesión, Necochea continúa fortaleciendo el trabajo conjunto entre el sector público y privado, promoviendo herramientas que potencien la calidad de los servicios turísticos y consoliden al destino como una propuesta cada vez más competitiva, sostenible y preparada para los desafíos del turismo actual.', '2026-06-02', NULL, NULL, 1, '2026-06-25 11:29:43'),
(30, 'Clima de Mundial, Urban Fest y propuestas para toda la familia: Turismo presenta las actividades de junio', '[\"/img/noticia/30/clima-de-mundial-urban-fest-y-propuestas-para-toda-la-famili_2026-06-25_1.png\"]', 'Conocé la agenda con diferentes eventos para el sexto mes del año', 'La Secretaría de Turismo y Desarrollo Productivo de la Municipalidad de Necochea, a cargo de Matías Sierra, dio a conocer la agenda de actividades prevista para el mes de junio, con una variada oferta de eventos deportivos, culturales y recreativos para disfrutar en distintos espacios de la ciudad.\r\n\r\nEntre las propuestas propias de la Secretaría, sobresalen una jornada especial de intercambio de figuritas y actividades temáticas en la Plaza Dardo Rocha, en la previa de un nuevo compromiso de la Selección Argentina en el Mundial de Fútbol 2026, y una nueva edición de la Urban Fest, una de las convocatorias más esperadas por los jóvenes del distrito, a través de la Subdirección de Juventud.\r\n\r\nLa programación también incluye iniciativas impulsadas por instituciones y organizaciones locales que cuentan con el acompañamiento y la promoción del área de Turismo.\r\n\r\nConcurso Hípico en la Sociedad Rural\r\n\r\nLos días sábado 13 y domingo 14 de junio se desarrollará la 3ª fecha del Circuito de Iniciados 2026 Zona Mar y Sierra, un importante concurso de saltos hípicos que tendrá lugar entre las 9:30 y las 18 en el predio de la Sociedad Rural de Necochea, ubicado en calles 106 y 63.\r\n\r\nCon entrada libre y gratuita para espectadores, el evento reunirá a jinetes, amazonas y familias vinculadas al mundo ecuestre, consolidando a Necochea como sede de una propuesta deportiva de relevancia regional.\r\n\r\nIntercambio de figuritas y clima mundialista en la Plaza Rocha\r\n\r\nEl lunes 15 de junio, desde las 14, la Plaza Dardo Rocha será escenario de una jornada especial para vivir la pasión mundialista junto a la comunidad.\r\n\r\n\r\nAdemás del tradicional intercambio de figuritas, habrá una kermés temática con juegos deportivos, concursos, sorteos, música, propuestas gastronómicas y una gigantografía de Lionel Messi para que grandes y chicos puedan disfrutar de la previa del partido de la Selección Argentina.\r\n\r\nLa actividad es organizada por la Secretaría de Turismo y Desarrollo Productivo.\r\n\r\nSegunda edición de la Noche de los Coros\r\n\r\nEl viernes 19 y sábado 20 de junio, desde las 19, el Teatro Municipal “Luis Sandrini” será sede de la segunda edición de la Noche de los Coros, una propuesta libre y gratuita que reunirá a destacadas agrupaciones corales de la región y del país.\r\n\r\n\r\n\r\nEl encuentro contará con la participación del Coro Vocal Kingdom, el coro La Experimental de Montevideo, la Agrupación Coral Colegiales y formaciones locales, además de talleres abiertos a la comunidad que se desarrollarán durante la mañana del sábado.\r\n\r\nLas entradas deberán retirarse previamente.\r\n\r\nRegresa la Urban Fest\r\n\r\nTambién el sábado 20, de 14 a 20, se realizará una nueva edición de la Urban Fest en el Centro Cultural Necochea.\r\n\r\nCon entrada libre y gratuita, el evento ofrecerá música en vivo, freestyle, graffiti, emprendedores, exposiciones y distintas expresiones del arte urbano, generando un espacio de encuentro, participación y entretenimiento para las juventudes del distrito.\r\n\r\nLa propuesta es organizada por la Subdirección de Juventud de la Municipalidad de Necochea.', '2026-06-01', NULL, NULL, 1, '2026-06-25 11:30:23'),
(31, 'Estudiantes de escuelas orientadas en Turismo viven una experiencia formativa', '[\"/img/noticia/31/estudiantes-de-escuelas-orientadas-en-turismo-viven-una-expe_2026-06-25_1.png\"]', 'Jóvenes que aprenden el turismo desde el territorio.', 'La Secretaría de Turismo y Desarrollo Productivo impulsa una propuesta educativa que conecta a estudiantes con la experiencia real del turismo local, promoviendo herramientas, conocimientos y nuevas oportunidades para su futuro profesional.\r\n\r\nLa iniciativa, que este año transita su tercera edición, reúne a alumnos del E.E.S. N° 5 y N° 13 con orientación en Turismo, junto a estudiantes de 3° y 4° año del Profesorado en Geografía del ISFD N° 163, quienes participan de encuentros y actividades prácticas vinculadas al funcionamiento de la actividad turística en el distrito.\r\n\r\n\r\n\r\nEl pasado martes se llevó adelante el primero de los tres encuentros previstos, dando inicio a una nueva etapa de esta capacitación que busca fortalecer el vínculo entre educación y el territorio.\r\n\r\nDurante las jornadas, los jóvenes conocen de cerca el trabajo que se desarrolla en la Oficina de Informes Turísticos, los principales atractivos de Necochea y Quequén, los servicios disponibles para visitantes y las distintas herramientas de orientación turística.\r\n\r\nLa experiencia incluye además recorridos por distintos puntos de interés de ambas localidades, fortaleciendo el vínculo entre la formación académica, la identidad local y el contacto directo con el turismo.\r\n\r\nEsta experiencia educativa pone en valor al turismo como una actividad generadora de oportunidades, intercambio y desarrollo, acercando a los estudiantes a experiencias concretas que contribuyen a su formación y los preparan para los desafíos del futuro.\r\n\r\nEducación, territorio y turismo articulados para seguir construyendo oportunidades para las nuevas generaciones.', '2026-05-27', NULL, NULL, 1, '2026-06-25 11:31:06'),
(32, 'Turismo comparte cartelería informativa con prestadores para jerarquizar espacios turísticos', '[\"/img/noticia/32/turismo-comparte-carteleria-informativa-con-prestadores-para_2026-06-25_1.png\"]', 'La Secretaría de Turismo y Desarrollo Productivo comenzó a compartir con prestadores turísticos la gráfica informativa utilizada en distintos espacios públicos del distrito, con el objetivo de fortale', 'La propuesta ya fue incorporada por el Camping Miguel Lillo, donde se instalaron carteles dedicados a las especies de aves que habitan el entorno natural del predio. Además, otros establecimientos, como Lago de los Cisnes, también manifestaron interés en sumarse a la iniciativa.\r\n\r\n\r\nEl material incluye diseños vinculados a temáticas locales, como aves del Parque Miguel Lillo, la Ballena Franca Austral o el corredor de buques hundidos, entre otros. Se entrega en formato PDF, listo para imprimir en tamaño 80 x 60 centímetros.\r\n\r\nAl respecto, el secretario de Turismo y Desarrollo Productivo, Matías Sierra, explicó que “es una articulación entre el sector privado y la Municipalidad, a través de la cual nosotros proveemos toda la información que el privado necesite acerca de lo que quiera comunicar dentro del camping”.\r\n\r\n\r\n\r\nAsimismo, destacó que “estamos fomentando mucho el QR con información que se va actualizando semanalmente, concerniente a todo lo turístico, actividades, gastronomía, hotelería y demás”.\r\n\r\nEn ese sentido, agregó que “la idea es poder trasladarlo a otros sectores, principalmente a campings, para que la gente que permanezca ahí tenga la posibilidad de escanear y acceder a toda la información turística desde su celular”.\r\n\r\nFinalmente, Sierra adelantó que “estamos trabajando en cuatro lugares más en los que iremos implementando esto en el transcurso de los meses venideros”.\r\n\r\nDesde el área invitaron a los interesados en desarrollar propuestas similares a comunicarse vía WhatsApp al 2262-431153 o acercarse a la oficina de Turismo, ubicada en avenida 2 y 87, para continuar trabajando en conjunto en la jerarquización de los espacios turísticos de Necochea', '2026-05-13', NULL, NULL, 1, '2026-06-25 11:31:45'),
(33, 'Subsidios de Turismo: hasta el 31 de mayo hay tiempo para presentar proyectos', '[\"/img/noticia/33/subsidios-de-turismo-hasta-el-31-de-mayo-hay-tiempo-para-pre_2026-06-25_1.png\"]', 'Los interesados en presentar proyectos que promuevan la igualdad de género y el turismo sostenible del distrito deberán presentar sus iniciativas según bases y condiciones.', 'Tomando como referencia las ediciones de años anteriores, la Secretaría de Turismo y Desarrollo Productivo a cargo de Matías Sierra, convoca a interesados en presentar proyectos que promuevan la igualdad de género y el turismo sostenible del partido de Necochea, y que se puedan materializar en la temporada de verano 2026/2027.\r\n\r\nLa presente iniciativa tiene por objeto brindar asistencia financiera para la compra de capital por un monto total de PESOS CUATRO MILLONES ($4.000.000), los cuales luego de finalizado el proceso de elección, se distribuirán de la siguiente manera: se otorgarán en total DOS (2) subsidios de PESOS DOS MILLONES ($2.000.000) cada uno –uno (1) destinado al programa cuyo objetivo es contribuir a la igual de género y diversidad; y otro (1) al programa de promoción del cuidado del medio ambiente y turismo sostenible.\r\n\r\nLos proyectos deberán presentarse en sobre cerrado, en la sede de la Secretaría de Turismo y Desarrollo Productivo ubicada en avenida 2 N° 4301, de 8 a 14 horas, hasta el 31 de mayo del presente año.\r\n\r\nEl proyecto presentado con el objetivo de contribuir a la igualdad de género y diversidad deberá estar liderado por mujeres, mientras que la iniciativa, que tendrá el objetivo de contribuir a la promoción del cuidado del medio ambiente, deberá promover el turismo sostenible.\r\n\r\nEn los dos casos, debe quedar demostrado que se puede llevar a cabo en algún lugar del distrito de Necochea. Se informa a los interesados que para poder participar de la convocatoria deben leer las bases y condiciones que se adjuntan a continuación y que se encuentran publicadas en la página web www.necochea.gov.ar y en www.necochea.tur.ar, o bien acercarse a la sede de la mencionada Secretaría a solicitar una copia.', '2026-05-12', NULL, NULL, 1, '2026-06-25 11:33:05'),
(34, 'Buenos Anfitriones va por su tercer año e invita a los más chicos a descubrir los secretos de la ciudad', '[\"/img/noticia/34/buenos-anfitriones-va-por-su-tercer-ano-e-invita-a-los-mas-c_2026-06-25_1.png\"]', 'Con la participación del Jardín N° 901, se puso en marcha oficialmente la 3° Edición Buenos Anfitriones, el programa de visitas guiadas, una iniciativa de la Secretaría de Turismo y Desarrollo Product', 'El proyecto, que se extenderá hasta el mes de septiembre, no es solo un paseo; es una herramienta pedagógica adaptada a los contenidos de cada sala y aula. La gestión garantiza de forma 100% gratuita tanto el traslado en micro como el acompañamiento de guías especializados, asegurando que la igualdad de oportunidades llegue a cada rincón del distrito.\r\n\r\n\r\n\r\nLos pilares del programa:\r\n\r\nIdentidad local: los chicos aprenden a amar lo que conocen, recorriendo puntos estratégicos de Necochea y Quequén.\r\n\r\nEducación en movimiento: el recorrido se alinea con lo que los alumnos están aprendiendo en clase, transformando la ciudad en un aula abierta.\r\n\r\nCompromiso Municipal: el Municipio, a través de la Secretaría de Turismo y Desarrollo Productivo facilita toda la logística para que las instituciones educativas solo tengan que preocuparse por disfrutar la experiencia.\r\n\r\n\r\n\r\n“Estamos formando hoy los mejores anfitriones del mañana”, destacaron desde la organización, subrayando que el sentido de pertenencia es el primer paso para una ciudad que cuida su patrimonio y recibe al turismo con orgullo.', '2026-04-29', NULL, NULL, 1, '2026-06-25 11:34:42'),
(35, 'Se invita a una visita guiada que ayudará a conocer la historia de la Villa Balnearia', '[\"/img/noticia/35/se-invita-a-una-visita-guiada-que-ayudara-a-conocer-la-histo_2026-06-25_1.png\"]', 'Será este sábado 2 de mayo por diferentes puntos emblemáticos y arquitectónicos de la Villa Díaz Vélez.', 'La Secretaría de Turismo y Desarrollo Productivo de la Municipalidad, invita a vecinos y turistas a participar de una enriquecedora jornada de descubrimiento patrimonial el próximo sábado 2 de mayo. Se trata de una visita guiada a pie, con participación libre y gratuita, que recorrerá los hitos históricos y arquitectónicos más relevantes de la Villa Díaz Vélez.\r\n\r\nLa actividad comenzará puntualmente a las 13:30 horas, teniendo como punto de partida la sede de la Secretaría de Turismo, ubicada en Avenida 2 y calle 87. El recorrido, de carácter libre y gratuito, tendrá una duración aproximada de 45 minutos y culminará con una experiencia única en el corazón espiritual de la Villa.\r\n\r\n\r\nDurante la caminata por la emblemática peatonal 83 hacia la Plaza San Martín, los asistentes podrán conocer los detalles que dieron forma a los edificios históricos del sector balneario. La guía especializada abordará la planificación urbana y las características distintivas que definen la identidad de nuestra ciudad.\r\n\r\nIngreso especial a la Parroquia Nuestra Señora de Lourdes\r\n\r\nEl punto culminante de la visita será el ingreso a la Parroquia Nuestra Señora de Lourdes (calle 6 entre 83 y 85), un edificio que rompe con los esquemas tradicionales. Fundada oficialmente el 26 de diciembre de 1957, la iglesia es el resultado de un esfuerzo comunitario que comenzó en 1949.\r\n\r\nComo distinción especial en esta jornada, el párroco actual acompañará y compartirá con los visitantes el significado de los tesoros que alberga el templo y detalles como su diseño innovador, el legado histórico y el espacio lateral con la réplica de la Gruta de Lourdes y el recientemente inaugurado “Paseo de Oración y Paz”.\r\n\r\nAl finalizar la actividad, se hará entrega de recuerdos de Necochea. Para más información, los interesados en participar podrán dirigirse a la Secretaría de Turismo y Desarrollo Productivo a través del Whatsapp 2262-431153 o en la web oficial www.necochea.tur.ar.', '2026-04-29', NULL, NULL, 1, '2026-06-25 11:35:16'),
(36, 'Turismo promociona una variada agenda de eventos para disfrutar de Necochea en mayo', '[\"/img/noticia/36/turismo-promociona-una-variada-agenda-de-eventos-para-disfru_2026-06-25_1.png\"]', 'En constante articulación con el sector privado, la Secretaría de Turismo y Desarrollo Productivo de la Municipalidad de Necochea dio a conocer una nutrida agenda de actividades para el quinto mes del', 'El calendario comenzará el venidero domingo 10 con un paseo de velocidad controlada organizado por el Club Mercedes Benz (Filial Mar del Plata). Desde las 13, alrededor de 40 autos antiguos y de colección arribarán a la ciudad, con presentación en el Centro Vasco y posterior caravana por Necochea. El evento contará con la presencia de Oscar y Juan Rodrigo Fangio, junto a Tulio Crespi, y será libre y gratuito.\r\n\r\n\r\nEl sábado 16 tendrá como gran atractivo el evento boxístico “Golpe Solidario”, que se desarrollará desde las 20 hasta la medianoche en el Polideportivo Municipal “Edgardo Hugo Yelpo”, con peleas profesionales —incluido un título argentino en juego—, televisación de Fox Sports y combates amateurs, a beneficio de instituciones locales. Para más detalles, el contacto es Miguel Álvarez al 2262-355908.\r\n\r\nEse mismo fin de semana, entre el sábado 16 y domingo 17, se disputará en Necochea/Quequén la 3ª fecha del Circuito Argentino de SUP Race, con competencias en modalidades sprint, técnico y long distance, consolidando a la región como sede destacada de este deporte. Organiza la Asociación Argentina de Surf y el contacto es Lito Labarthe, al 2262-493955.\r\n\r\nEn tanto, el domingo 17, el Parque Miguel Lillo será escenario de la tercera fecha del Open Bonaerense de Cross Country Olímpico (XCO), una competencia de mountain bike que reunirá a unos 200 ciclistas de distintas categorías. La organización está a cargo de Marcela Martinengo, y el Contacto es Pablo Bianchi al 2262-614565.\r\n\r\n\r\nAdemás, para el fin de semana largo del 23 al 25 de mayo, la agenda también ofrece múltiples alternativas, como el Quequén Classic de Surf y Longboard en playas de Quequén, organizado por Ariel Schmidt, cuyo contacto es 2262-478708.\r\n\r\nAdemás, se anuncia una caminata y trekking guiado en el Parque Miguel Lillo, que será el sábado 23 a partir de las 9 desde el Circuito Aeróbico de Pinolandia y 10. La actividad libre y gratuita, organizada por la Dirección de Deportes, estará a cargo de la Prof. Adriana Lucifora y se pide como único requisito asistir con diez minutos de anterioridad.\r\n\r\n\r\nEn tanto, el mismo sábado 23, desde las 13 hs. habrá una muestra fotográfica con recorrido guiado en el Museo Histórico Regional del Parque Miguel Lillo, también de participación libre y abierta a la comunidad.\r\n\r\nFinalmente, el cierre del mes llegará con el deporte motor: el sábado 30 y domingo 31 se desarrollará el campeonato Arena Series de Enduro en el Campo Pinar de Bahía S.A., en Quequén, una competencia de nivel provincial que convoca a motos y cuatriciclos sobre superficie de arena. El Contacto es Paul Adrián Urfini, al 11 65427166.\r\n\r\n\r\nDesde el área de Turismo destacaron que esta agenda diversa “permite romper con la estacionalidad y seguir posicionando a Necochea y Quequén como destinos activos durante todo el año”, invitando a vecinos y visitantes a participar de cada una de las propuestas.', '2026-05-04', NULL, NULL, 1, '2026-06-25 11:36:02'),
(37, 'Necochea participó de la asamblea del Consejo Provincial de Turismo', '[\"/img/noticia/37/necochea-participo-de-la-asamblea-del-consejo-provincial-de-_2026-06-25_1.png\"]', 'El encuentro del COPROTUR fue encabezado por el ministro Augusto Costa y sirvió para fortalecer vínculos de promoción conjunta.', 'Representantes del área de Turismo del municipio de Necochea participaron de la 32° Asamblea del Consejo Provincial de Turismo (COPROTUR), desarrollada en Punta Indio, un encuentro que reunió a referentes bonaerenses vinculados a la actividad turística con el objetivo de fortalecer el trabajo articulado entre los distintos destinos de la provincia.\r\n\r\nDurante la jornada, la delegación local mantuvo reuniones e intercambios con referentes turísticos de las ciudades de Mercedes, Berisso, General Lavalle, Mar Chiquita, Cañuelas y Moreno, avanzando en futura acciones de promoción turística conjunta, generación de convenios y estrategias de trabajo colaborativo entre municipios.\r\n\r\n\r\nEl encuentro estuvo encabezado por el ministro de Producción, Ciencia e Innovación Tecnológica de la Provincia de Buenos Aires, Augusto Costa, junto al intendente de Punta Indio, David Angueira, y la Subsecretaria de Turismo Bonaerense, Soledad Martínez.\r\n\r\nDurante la asamblea se abordaron distintos ejes vinculados al fortalecimiento del turismo en la provincia, destacándose la inversión del Estado bonaerense en fiestas populares y programas de desarrollo turístico. Además, se presentaron herramientas y programas destinados a acompañar al sector, con Sello de Calidad Turística Bonaerense.\r\n\r\nLa participación de Necochea en este tipo de espacios permite seguir consolidando vínculos institucionales, generar nuevas oportunidades de promoción y continuar posicionando al distrito dentro de las estrategias turísticas en la provincia.\r\n\r\nEl COPROTUR es un espacio de articulación integrado por municipios, regiones turísticas y organismos vinculados al sector, que trabaja en el diseño de políticas públicas y acciones coordinadas para impulsar el desarrollo turístico de la Provincia de Buenos Aires, promoviendo el intercambio de experiencias y fortaleciendo el turismo como motor económico y social.', '2026-05-11', NULL, NULL, 1, '2026-06-25 11:36:31'),
(38, '“Escapada a Necochea”: la ciudad se prepara para días a puro rock, naturaleza y adrenalina al aire libre – Municipalidad de Necochea', '[\"/img/noticia/38/escapada-a-necochea-la-ciudad-se-prepara-para-dias-a-puro-ro_2026-06-25_1.png\"]', 'Desde este miércoles 29, y durante el primer fin de semana largo de mayo, se destacan varios eventos culturales, sociales y deportivos en la ciudad.', 'Necochea se prepara para el primer fin de semana largo de mayo con rock, naturaleza y un desafío deportivo. En ese sentido, la Secretaría de Turismo y Desarrollo Productivo armó un cronograma con cada uno de los eventos, anticipándose el primero de ellos al fin de semana con la presentación en la ciudad de la reconocida banda de rock “No te va a gustar”.\r\n\r\nDesde la Secretaría de encabeza Matías Sierra, resaltan que Necochea se prepara para recibir a la gente con una agenda que combina la potencia del mejor rock rioplatense, la calma de los paisajes naturales incomparables de Necochea y la adrenalina del deporte de aventura.\r\n\r\n\r\n“El descanso que te merecés con rock, naturaleza y desafío en un Fin de Semana XL Inolvidable ¿Sentís que el año ya arrancó a mil? El próximo fin de semana largo no es solo una fecha en el calendario; es tu oportunidad para frenar la rutina, recargar energías y celebrar el fruto de tu esfuerzo como corresponde”, invitaron desde Turismo.\r\n\r\nDesde el rugir de las guitarras de No Te Va a Gustar este miércoles en el histórico Cine Teatro París, hasta el desafío épico del Neco Trail Run entre bosques y médanos, la ciudad ofrece propuestas para todos los gustos. “Es el momento ideal para una escapada que combine aire puro del Parque Miguel Lillo con la calidez de nuestra cultura local”.\r\n\r\nCRONOGRAMA DE ACTIVIDADES\r\n\r\nMiércoles 29 de abril\r\n\r\n-Show: No Te Va a Gustar (NTVG)\r\nHora: 21 hs.\r\nLugar: Cine Teatro París (Av. 59 N° 2868)\r\nDetalle: La banda uruguaya presenta su gira “Florece en el Caos”.\r\nEntradas: Desde $ 65.000 (disponibles en Articket o ADN Store,calle 61 N° 2813.\r\n\r\n\r\n\r\nSábado 2 de mayo\r\n\r\n-Caminata y Trekking por el Parque Miguel Lillo\r\nHora: 09:00 hs. (presentarse 10 min antes)\r\nSalida: Circuito aeróbico (Pinolandia y Av.  10).\r\nDetalle: Actividad al aire libre y gratuita a cargo de la Prof. Adriana Lucifora. Dos horas de intensidad natural.\r\n\r\n-Visita Guiada: Plaza San Martín y Capilla Ntra. Sra. De Lourdes\r\nHora: 13:30 hs.\r\nSalida: Secretaría de Turismo y Desarrollo Productivo, Av.  2 y calle 87.\r\nDetalle: Recorrido histórico a pie (45min.) Actividad gratuita con entrega de recuerdos de la ciudad.\r\n\r\n\r\n\r\nDomingo 3 de mayo\r\n\r\n-Neco Trail Run (Carrera de Aventura)\r\nLargada: 10:00 hs. desde Balneario Kabryl.\r\nCircuito: Bosque, senderos, médanos y vistas al mar y parque eólico\r\nDistancias: 20K (El gran desafío), 10 k (Técnica y Resistencia) y 5K (Participativa)\r\nInscripciones: https://www.google.com/search?q=necotrail.cerokogroup.com\r\n\r\nTodos los días (Paseo Recomendado)\r\n\r\nColonia de Lobos y Galería “Mar Adentro”\r\nLugar: Escollera Sur, Puerto Quequén.\r\nDetalle: Avistaje de lobos marinos y recorrido por el mural “Reflejos” (1000 metros de arte frente al mar).\r\nAcceso: Gratuito y libre.\r\n\r\n\r\n\r\n\r\nInformación Útil para tu visita\r\n\r\nAlojamientos y Gastronomía: Consultá todas las opciones en la Secretaría de Turismo y Desarrollo Productivo en Av. 2 y 87.\r\nClima: Ideal para actividades al aire libre; ¡no olvides traer calzado cómodo y abrigo para la tarde!\r\n\r\n«¡Te esperamos en Necochea para renovar energías! Más información en www.necochea.tur.ar; en redes sociales necocheatur o al whatsapp 2262-431153?.', '2026-04-28', NULL, NULL, 1, '2026-06-25 11:37:18'),
(39, 'Hay planes para este ‘finde’ en Neco: encuentros deportivos, recitales y música en vivo', '[\"/img/noticia/39/hay-planes-para-este-finde-en-neco-encuentros-deportivos-rec_2026-06-25_1.png\"]', 'La Secretaría de Turismo acompaña en la promoción de numerosos eventos en la ciudad para el venidero fin de semana, el último de abril.', 'Gracias a la constante articulación con el sector privado para la generación de eventos de calidad, la Secretaría de Turismo y Desarrollo Productivo, a cargo de Matías Sierra, auspicia el anticipo de un fin de semana en la ciudad con varios planes para toda la familia.\r\n\r\nEn la agenda, resaltan encuentros deportivos de suma atracción y primer nivel, como así también recitales y música en vivo. A continuación, se comparte todo el detalle.\r\n\r\nEventos fin de semana\r\n\r\nSábado 25 – Encuentro de Rugby Infantil Club Náutico de 09 a 12:30 hs. (Ribera río Quequén)\r\n\r\nEl Club Náutico de Necochea se prepara para ser el anfitrión de un importante encuentro de rugby infantil este viernes 14 de junio. Las categorías menores del club recibirán a cerca de 300 jugadores de seis instituciones de la Unión de Rugby de Mar del Plata (URMDP).\r\n\r\nSe espera una gran concurrencia de familias y aficionados del rugby para acompañar a los jóvenes deportistas en esta jornada de confraternidad y crecimiento deportivo en las instalaciones del Club Náutico.\r\n\r\nContacto Claudia de Lucca 2262-361988\r\n\r\n\r\n\r\nSábado 25 y domingo 26 –Arena Race (quinta edición).\r\n\r\nCarrera con y sin obstáculos, Club Villa del Parque, Parque Miguel Lillo y Playa(entre muelle y camping Las Grutas) de 8 a 14 hs.\r\n\r\nLa propuesta incluirá distintas competencias pensadas para todos los niveles, desde quienes se inician en este tipo de carreras hasta corredores más experimentados. Además, el evento contará con actividades para toda la familia y propuestas recreativas.\r\n\r\nLas pruebas estarán diseñadas para que puedan participar corredores individuales, duplas o equipos. La actividad incluye Arenita Kids (carrera de obstáculos para niños desde las 13 horas del sábado)\r\n\r\nLa organización destaca especialmente la prueba OCR 100, que tendrá un formato similar a “Ninja Warrior”. Además, el evento contará con DJ en vivo, puestos gastronómicos y un show de atletas internacionales de obstáculos, convirtiéndose en una propuesta deportiva y recreativa para toda la comunidad.\r\n\r\nMás de 30 localidades del país estarán representadas en esta edición, lo que posiciona a Necochea como sede de un evento deportivo con impacto turístico, y para más información e inscripciones, los interesados pueden ingresar al Instagram oficial @arena.race o ingresar en este enlace. Organizador: Joaquín Garona 1134215790\r\n\r\n\r\n\r\nSábado 25 y Domingo 26 –Provincial de Tenis en Sum Colegio Danés (calle 43 Nº 2920)\r\n\r\nNecochea se prepara para recibir un evento deportivo de gran relevancia: la primera fecha de la Liga Provincial de Tenis de Mesa de Buenos Aires con la participación de delegaciones de distintos puntos de la provincia.\r\n\r\nLa organización estará a cargo de la Agrupación de Tenis de Mesa Necochea.\r\n\r\nEl torneo se desarrollará en el gimnasio del Colegio Danés Alta Mira, donde se espera la participación de más de 300 jugadores. Para ello, se dispondrá un montaje de 16 mesas profesionales, en las que se disputarán 128 cruces entre equipos de distintas localidades.\r\n\r\nLa competencia se llevará adelante bajo la modalidad Copa Davis, con enfrentamientos compuestos por cinco partidos: dos singles, un doble y otros dos singles. El certamen estará dividido en cinco categorías, con una intensa programación que incluye 9 cruces en Primera, 23 en Segunda, 38 en Tercera, 22 en Cuarta y 36 en Quinta.\r\n\r\nEl torneo se perfila como una oportunidad única para disfrutar de un espectáculo deportivo de alto nivel, con la presencia de algunos de los mejores exponentes del tenis de mesa provincial, consolidando a Necochea como sede de importantes eventos deportivos.\r\n\r\n\r\nRecitales:\r\n\r\nAxel “25 Tour”. Sábado 25 en el cine teatro París. (avenida 59 Nº 2868)\r\n\r\nAxel se presenta en Necochea con un show totalmente renovado, celebrando 25 años de trayectoria y presentando oficialmente su nuevo álbum “Vuelve”. Un concierto con gran impacto sonoro y visual, clásicos de siempre en versiones nuevas y un recorrido emocional único. En el repertorio no faltarán hits como Amo, Miradas, Todo mi mundo, Te voy a amar, Celebra la vida, junto a las canciones de su último disco.\r\n\r\nAxel cierra un 2025 histórico con más de 60 shows y en 2026 continuará su gira por América y Europa.\r\n\r\nEntradas anticipadas\r\nEn efectivo: ADN Store (61 N° 2813)\r\nOnline: www.articket.com.ar\r\n\r\nMúsica en vivo (Viernes y sábado) en La Sardiñola (67 Nº 2902), Wo Cultural (85 Nº 261), Don Atilio (81 Nº 263),  Mediterráneo (4 Nº 4352), Primera Junta (64 entre 57 y 59)  .  \r\n\r\nMás información en www.necochea.tur.ar; en redes necocheatur, o por whatsapp 2262-431153', '2026-04-22', NULL, NULL, 1, '2026-06-25 11:38:03'),
(40, 'Turismo lanza subsidios a proyectos que promuevan la igualdad de género y la sostenibilidad', '[\"/img/noticia/40/turismo-lanza-subsidios-a-proyectos-que-promuevan-la-igualda_2026-06-25_1.png\"]', 'Los interesados deberán presentar sus iniciativas según bases y condiciones, con tiempo de hacerlo hasta el 31 de mayo del presente año', 'Tomando como referencia las ediciones de años anteriores, la Secretaría de Turismo y Desarrollo Productivo a cargo de Matías Sierra, convoca a interesados en presentar proyectos que promuevan la igualdad de género y el turismo sostenible del partido de Necochea, y que se puedan materializar en la temporada de verano 2026/2027.\r\n\r\nLa presente iniciativa tiene por objeto brindar asistencia financiera para la compra de capital por un monto total de PESOS CUATRO MILLONES ($4.000.000), los cuales luego de finalizado el proceso de elección, se distribuirán de la siguiente manera: se otorgarán en total DOS (2) subsidios de PESOS DOS MILLONES ($2.000.000) cada uno –uno (1) destinado al programa cuyo objetivo es contribuir a la igual de género y diversidad; y otro (1) al programa de promoción del cuidado del medio ambiente y turismo sostenible.\r\n\r\nLos proyectos deberán presentarse en sobre cerrado, en la sede de la Secretaría de Turismo y Desarrollo Productivo ubicada en avenida 2 N° 4301, de 8 a 14 horas, hasta el 31 de mayo del presente año.\r\n\r\n\r\n\r\n\r\nEl proyecto presentado con el objetivo de contribuir a la igualdad de género y diversidad deberá estar liderado por mujeres, mientras que la iniciativa, que tendrá el objetivo de contribuir a la promoción del cuidado del medio ambiente, deberá promover el turismo sostenible.\r\n\r\nEn los dos casos, debe quedar demostrado que se puede llevar a cabo en algún lugar del distrito de Necochea. Se informa a los interesados que para poder participar de la convocatoria deben leer las bases y condiciones que se adjuntan a continuación y que se encuentran publicadas en la página web www.necochea.gov.ar y en www.necochea.tur.ar, o bien acercarse a la sede de la mencionada Secretaría a solicitar una copia.', '2026-04-22', NULL, NULL, 1, '2026-06-25 11:38:44'),
(41, 'Necochea fue sede de la Regata Provincial de Kayak con más de 200 competidores', '[\"/img/noticia/41/necochea-fue-sede-de-la-regata-provincial-de-kayak-con-mas-d_2026-06-25_1.png\"]', 'Necochea volvió a posicionarse con su Río Quequén como escenario de grandes eventos deportivos al albergar la 2da edición de la Regata Provincial Maratón de kayak, que se desarrolló durante el fin de', 'El evento, organizado por el Club Náutico Necochea, contó con el acompañamiento de la Secretaría de Turismo y Desarrollo Productivo de la Municipalidad de Necochea, que brindó apoyo logístico y organizativo para garantizar el éxito de la competencia.\r\n\r\nLas pruebas se disputaron en distancias de 12 y 16 kilómetros, incluyendo tramos de acarreo en los que los participantes debían descender de sus embarcaciones y continuar a pie, completando un circuito exigente. Las condiciones climáticas acompañaron de manera ideal, favoreciendo el desarrollo de la actividad.\r\n\r\n\r\n\r\n\r\nParticiparon delegaciones provenientes de Tandil, Jáuregui, Campana, Lobería, Las Flores, San Pedro, General Belgrano, Olavarría, General Villegas, La Plata, Escobar, Azul, además de representantes locales.\r\n\r\nDesde la organización destacaron el acompañamiento de distintas instituciones, entre ellas la Cruz Roja, y remarcaron el impacto positivo del evento en la promoción del destino: muchos de los visitantes aprovecharon la ocasión para conocer y recorrer los atractivos naturales de Necochea, como el parque y las playas.\r\n\r\nDe esta manera, la ciudad continúa consolidándose como sede de eventos deportivos que combinan competencia, turismo y desarrollo local.', '2026-04-13', NULL, NULL, 1, '2026-06-25 11:39:28');

