INSERT INTO `que_hacer` (`id_servicio`, `nombre`, `img_url`, `descripcion`, `contacto`, `id_usuario`, `creado_en`, `filtros`) VALUES
(15, 'Surf', '[\"/img/que-hacer/15/surf_2026-06-24_1.png\"]', 'Gracias a su geografía particular, variada y extensa, tenemos los escenarios ideales para desarrollar actividades extremas al aire libre durante todo el año. Para una mejor presentación se engloban según el escenario natural de base', 'Sobre la costa', 1, '2026-06-24 23:04:03', NULL),
(16, 'Bodyboard', '[\"/img/que-hacer/16/bodyboard_2026-06-24_1.png\"]', 'Home » Qué hacer » Bodyboard\r\n\r\nEl bodyboard es un deporte basado en el deslizamiento sobre la superficie o pared de la ola con una tabla. Su tamaño puede variar en función de la altura y peso del rider.', 'Sobre la costa', 1, '2026-06-24 23:08:15', NULL),
(17, 'Cabalgatas', '[\"/img/que-hacer/17/cabalgatas_2026-06-24_1.png\"]', 'Una de las tantas actividades que se pueden realizar dentro del Parque Miguel Lillo', 'Tel. 2262-518531', 1, '2026-06-24 23:09:36', NULL),
(18, 'Parapente', '[\"/img/que-hacer/18/parapente_2026-06-24_1.png\"]', 'Viví Necochea desde el aire, experimentá Necochea extremo haciendo parapente', '02262-503048', 1, '2026-06-24 23:10:54', NULL),
(19, 'Pesca', '[\"/img/que-hacer/19/pesca_2026-06-24_1.png\"]', 'El Partido de Necochea cuenta con diversidad de ambientes acuáticos: río, mar y lagunas. Un destino ideal para disfrutar de la pesca variada durante todo el año', 'Sobre el rio quequen / Sobre las playas', 1, '2026-06-24 23:11:38', NULL),
(20, 'Excursiones 4X4', '[\"/img/que-hacer/20/excursiones-4x4_2026-06-24_1.png\"]', 'Excursiones 4 X 4 divertidas para hacer en familia por las grandes playas y Gran Médano Blanco', '2262-477106', 1, '2026-06-24 23:15:56', NULL);

