INSERT INTO `que_visitar` (`id_lugar`, `nombre`, `img_url`, `descripcion`, `info`, `contacto`, `id_usuario`, `creado_en`, `filtros`) VALUES
(14, 'Lago de los Cisnes', '[\"/img/que-visitar/14/lago-de-los-cisnes_2026-06-24_1.jpg\",\"/img/que-visitar/14/lago-de-los-cisnes_2026-06-24_2.jpg\",\"/img/que-visitar/14/lago-de-los-cisnes_2026-06-24_3.jpg\",\"/img/que-visitar/14/lago-de-los-cisnes_2026-06-24_4.jpg\"]', 'Enmarcado por la playa y el Parque Miguel Lillo,  este lago artificial, nos permite apreciar distintos tipos de aves acuáticas.', 'Enmarcado por la playa y el Parque Miguel Lillo,  este lago artificial, nos permite apreciar distintos tipos de aves acuáticas. \r\n\r\nCon una programación adecuada, se pueden\r\ndesarrollar actividades tales como:\r\n\r\nPaseos guiados, circuitos\r\ntemáticos, juegos al aire libre.\r\n\r\nActividades de aventura controlada\r\n(senderismo, tirolesa, kayaks, granja, Parque Aéreo. Actividades nocturnas.\r\n\r\nEspacios de picnic, áreas de\r\ndescanso, espectáculos culturales al aire libre.\r\n\r\nUn polo gastronómico dentro del Lago de los Cisnes representa una oportunidad clave para poner en valor los saberes culinarios, los productos regionales y las tradiciones alimentarias de Necochea y su zona de influencia. Cocina en vivo, shows, ferias artesanales y comida al paso.\r\n\r\nSu ingreso es libre y gratuito. Se encuentra en Avenida 2 a metros de la Avenida Pinolandia, abierto todos los días a partir de las 9 hs.', '+5492262431153', 1, '2026-06-24 22:40:49', NULL),
(15, 'Parque Miguel Lillo', '[\"/img/que-visitar/15/parque-miguel-lillo_2026-06-24_1.jpg\"]', 'El Parque Miguel Lillo se encuentra localizado desde la Calle 89 hacia el oeste, entre la Avenida 2 y la Avenida 10, la que le da acceso a las playas de la costa y al mar', 'El Parque Miguel Lillo se encuentra localizado desde la Calle 89 hacia el oeste, entre la Avenida 2 y la Avenida 10, la que le da acceso a las playas de la costa y al mar. Es uno de los distintivos de la ciudad de Necochea, ya que cuenta con una extensión 640 hectáreas y más de un millón de especies arbóreas (en su mayoría coníferas) que son el resguardo de aves de esta zona.\r\n\r\nDesde la perspectiva turística – recreativa es posible dividirlo de la siguiente manera: en primer lugar/área, presenta las características de un parque urbano, se encuentran la ex Administración del Parque, donde hoy funciona en la Casona del Museo Histórico Egistro Ratti, que fue primero la Casa de la familia Díaz Vélez y luego Administración y vivienda del Director del Parque Edgar Gatti, el Anfiteatro, y el Área de Museos emplazado en la casa de veraneo de los Díaz Vélez  de marcado estilo neocolonial. Esta fue edificada por Carmen Díaz Vélez de Álvarez de Toledo. También se encuentran juegos infantiles y fogones. La segunda área es la parte que se encuentra más densamente arbolada con los circuitos internos, el circuito aeróbico, el jardín francés y japonés, jardín de rocas. Por último la tercera área tiene su núcleo en la Avenida Pinolandia donde se pueden alquilar bicicletas, carrilindos, caballos y dar un paseo dentro del tren ecológico del Parque Miguel Lillo.\r\n\r\nContemporáneamente, se originó el desarrollo de emprendimientos de urbanización costeros en zonas no aptas para actividades agropecuarias.', '+5492262431153', 1, '2026-06-24 22:43:17', NULL),
(16, 'Playas del centro', '[\"/img/que-visitar/16/playas-del-centro_2026-06-24_1.jpg\"]', 'Necochea es un destino ideal para disfrutar todo el año, con escenarios naturales únicos, con una rica historia y cultura, que se conjugan con un equipamiento acorde a todas las necesidades y preferencias.', 'Necochea es un destino ideal para disfrutar todo el año, con escenarios naturales únicos, con una rica historia y cultura, que se conjugan con un equipamiento acorde a todas las necesidades y preferencias.\r\nEn la zona comprendida en Avenida 2 entre las calles 73 y Pinolandia se ubican los balnearios con servicios de playas, con el alquiler de sombrillas y carpas, sanitarios y un variada propuesta de gastronomía, recreación, piscinas e instalaciones deportivas.\r\nEn la calle 83 se encuentra la Rambla Municipal, sitio de encuentro emblemático desde su creación en el año 1910.', '+5492262431153', 1, '2026-06-24 22:43:58', NULL),
(17, 'Centro de Interpretación Portuaria', '[\"/img/que-visitar/17/centro-de-interpretacion-portuaria_2026-06-24_1.png\"]', 'Tiene como objetivo explicar de manera clara, didáctica y accesible como funciona la operatoria del puerto, cuál es su historia y qué rol estratégico cumple en el desarrollo productivo, económico y social en la región', 'Tiene como objetivo explicar de manera clara, didáctica y accesible como funciona la operatoria del puerto, cuál es su historia y qué rol estratégico cumple en el desarrollo productivo, económico y social en la región. A través de contenidos interactivos, materia audiovisual y gráfico, muestras de fotografías históricas  y re cursos educativos, el CIP permite comprender el recorrido completo de la actividad portuaria: desde el arribo de los granos y mercaderías, el trabajo diario de los portuarios, hasta la salida de los busques hacia los mercados internacionales.\r\n\r\nEl espacio también pone en valor la identidad portuaria de Quequén, Necochea y de todo el sudeste bonaerense, destacando el aporte de más de 5 generaciones de trabajadores, la evolución de la infraestructura portuaria y la importancia del puerto como motor del hinterland productivo de la región.\r\n\r\nPensado especialmente para estudiantes, residentes, turistas e instituciones, el CIP se consolidad como una herramienta clave de educación, transparencia y vinculación comunitaria, permitiendo conocer de cerca una actividad fundamental para el desarrollo local y regional.\r\n\r\nEstá ubicado en el acceso de la Escollera Sur.', '+5492262431153', 1, '2026-06-24 22:44:53', NULL),
(18, 'Paseo de la Ribera', '[\"/img/que-visitar/18/paseo-de-la-ribera_2026-06-24_1.png\",\"/img/que-visitar/18/paseo-de-la-ribera_2026-06-24_2.png\"]', 'Al camino que bordea el Río Quequén entre la bajada por la calle 66 hasta el Puente Taraborelli se lo conoce como “Paseo de la Ribera”.', 'Al camino que bordea el Río Quequén entre la bajada por la calle 66 hasta el Puente Taraborelli se lo conoce como “Paseo de la Ribera”.\r\n\r\nAllí se levanta infraestructura y equipamientos alternados con viviendas particulares, incluso clubes e instituciones han elegido este hermoso marco para instalar sus centros de recreación y deportes, además de emprendimientos gastronómicos.\r\n\r\nSe pueden encontrar los complejos de: Necopesca Club, Rowing Club, Club Del Valle, Luz y Fuerza, Sociedad Española, Casineros, entre otros.\r\n\r\nEn el margen del río se alternan miradores, juegos y espacios de descanso.\r\n\r\nPara los amantes de la pesca hay recodos ideales donde se puede capturar especies como pejerreyes, lisas, truchas, dentudos y bagres. Cuenta con servicio de proveeduría, baños, parrillas y juegos para niños.', '+5492262431153', 1, '2026-06-24 22:45:46', NULL),
(19, 'Playas de Quequén', '[\"/img/que-visitar/19/playas-de-quequen_2026-06-24_1.png\"]', 'Las playas de Quequén, a diferencia de las de Necochea, presentan una marcada erosión con playas más angostas de arenas más gruesas y mayor presencia de conchillas, caracoles y formaciones rocosas en toda su extensión.', 'Las playas de Quequén, a diferencia de las de Necochea, presentan una marcada erosión con playas más angostas de arenas más gruesas y mayor presencia de conchillas, caracoles y formaciones rocosas en toda su extensión.\r\nOtra característica es la presencia visible de restos de buques encallados.\r\nComienzan en la escollera Norte hasta el Balneario Costa Bonita, en toda esta extensión se alternan playas para el disfrute del baño, de actividades náuticas como surf, bodyboard y kayak.\r\nTambién presenta un sector de servicios con unidades de sombras, gastronomía e incluso opciones de alojamiento en camping y bungalós.', '+5492262431153', 1, '2026-06-24 22:46:14', NULL),
(20, 'Termas del Campo Médano Blanco', '[\"/img/que-visitar/20/termas-del-campo-medano-blanco_2026-06-24_1.png\"]', 'Enmarcado por la naturaleza campestre, el casco principal de una estancia fue adaptado y sobre un costado se construyeron las modernas instalaciones.', 'Ubicado a unos 40 kilómetros de la ciudad, este complejo inaugurado en 2012 propone el descanso y relax ideales para las vacaciones.\r\n\r\nEnmarcado por la naturaleza campestre, el casco principal de una estancia fue adaptado y sobre un costado se construyeron las modernas instalaciones.\r\n\r\nServicios básicos:\r\nDos piscinas cubiertas con agua termal; dos hidromasajes al aire libre con agua termal; una piscina climatizada recreativa al aire libre; sanitarios, vestuarios y duchas; atención médica permanente; estacionamiento; clases de aquagym, aquarelax, aquamove, stretching; cancha de vóley; actividades recreativas y educativas para niños de 5 a 12 años; juegos de mesa; áreas de picnic.\r\n\r\nServicios opcionales:\r\nFogones (con previa reserva); alquiler de casilleros con llave; alquiler de batas; alquiler de toallones; alquiler de short de baño para hombre; alquiler de ojotas; alquiler de camastros; alquiler de kayak; Spa; gastronomía.', '(02262) 42-3795 / 2262476802 / 2262631722', 1, '2026-06-24 22:47:08', NULL),
(21, 'Parque Eólico \"Vientos de Necochea\"', '[\"/img/que-visitar/21/parque-eolico-vientos-de-necochea_2026-06-24_1.png\"]', 'El Parque Eólico “Vientos de Necochea”, ocupa 158 hectáreas con once aerogeneradores de tecnología Vestas en una posición privilegiada, y produce anualmente 158.000 MW de energía limpia, equivalentes al consumo de 52 mil hogares.', 'El Parque Eólico “Vientos de Necochea”, ocupa 158 hectáreas con once aerogeneradores de tecnología Vestas en una posición privilegiada, y produce anualmente 158.000 MW de energía limpia, equivalentes al consumo de 52 mil hogares.\r\n\r\nSe encuentra frente al mar, donde finaliza la zona urbana de la ciudad, en Avenida 10 y calle 225, hacia el oeste. Por su imponente altura y vista desde casi toda la costa, se han convertido en otra de las postales características de la ciudad.', '+5492262431153', 1, '2026-06-24 22:49:44', NULL),
(22, 'Reserva Natural Arroyo Zabala', '[\"/img/que-visitar/22/reserva-natural-arroyo-zabala_2026-06-24_1.png\"]', 'Se encuentra en la zona de médanos de la desembocadura del Arroyo Zabala, entre los Partidos de Necochea y San Cayetano.', 'Se encuentra en la zona de médanos de la desembocadura del Arroyo Zabala, entre los Partidos de Necochea y San Cayetano.\r\n\r\nComprende 2.800 hectáreas de ambos lados de San Cayetano y Necochea ubicadas en la desembocadura del arroyo homónimo. Es una muestra representativa y complementaria de costa medanosa transicional y ambientes asociados con ecosistemas de gran importancia por estar adaptados al intercambio de agua dulce y salobre.\r\n\r\nNo presenta grandes transformaciones ambientales, lo que permite mantener condiciones en el medio para albergar los procesos naturales dinámicos de la costa y contener una muestra representativa de la flora y fauna costera. Entre los primeros, encontramos pastos como la espartina, cortaderas y pequeños arbustos. En cuanto a la fauna se encuentran el carpincho, yarará ñata, escuercito chico y lagartijas, mientras que entre las aves habitan el pecho colorado, el espartillero enano y el ñandú, entre otros.\r\n\r\nDentro de la Reserva no está permitido el uso de ningún tipo de vehículos.\r\nEl visitante podrá, con previo pedido de autorización, realizar actividades de investigación científica y otras acorde a la categoría de manejo del área (siendo actividades de educación y divulgación en desarrollo).', 'La ubicación es -38.724051021368716, -59.33011689680721', 1, '2026-06-24 22:51:10', NULL),
(23, 'Playa Punta Negra', '[\"/img/que-visitar/23/playa-punta-negra_2026-06-24_1.png\"]', 'Ubicado a 16 kilómetros hacia el sudoeste desde el Centro de la ciudad de Necochea, este paraje se caracteriza por sus formaciones rocosas que bajan desde los acantilados internándose en el mar, brindando un paisaje único', 'Ubicado a 16 kilómetros hacia el sudoeste desde el Centro de la ciudad de Necochea, este paraje se caracteriza por sus formaciones rocosas que bajan desde los acantilados internándose en el mar, brindando un paisaje único. Este capricho natural permite la formación de piletas donde diversas especies de peces, moluscos y plantas marinas encuentran su hábitat, sorprendiendo así a los visitantes con vivencias y observaciones únicas.\r\n\r\nEl nombre Punta Negra se le asigna por el color negro dominante de la arena que se encuentra enriquecida por hierro.\r\nSu encanto es variante, ya que el ir y venir de las mareas hace que los piletones y las escolleras naturales aparezcan y desaparezcan brindando diferentes paisajes.\r\n\r\nLa pesca también se hace presente con especies como pejerrey, bagre, dentudo y carpa.\r\n\r\nEs un sitio de diverso atractivo que permite ir desde la contemplación serena de la naturaleza hasta el disfrute activo de las olas ya que está considerado uno de los mejores points para el surf.\r\nSe puede acceder con vehículo de tracción simple por un camino de tierra, con máxima precaución los días de lluvias o posteriores inmediatos a ellos; y, por camino costero únicamente en 4×4.', NULL, 1, '2026-06-24 22:52:04', NULL),
(24, 'Balneario Los Ángeles - Cueva Del Tigre', '[\"/img/que-visitar/24/balneario-los-angeles-cueva-del-tigre_2026-06-24_1.png\"]', 'Ubicado a 35 kilómetros hacia el sudoeste desde el centro de la ciudad de Necochea, este particular paraje se caracteriza por sus amplias playas de arenas gruesas, acantilados y plataformas rocosas introduciéndose en el mar hasta 200 metros de la costa, configuran su mayor atractivo', 'Ubicado a 35 kilómetros hacia el sudoeste desde el centro de la ciudad de Necochea, este particular paraje se caracteriza por sus amplias playas de arenas gruesas, acantilados y plataformas rocosas introduciéndose en el mar hasta 200 metros de la costa, configuran su mayor atractivo. En este paraje se encuentra la gruta conocida como Cueva del Tigre. Según cuenta la leyenda, este refugio albergó al bravío Tigre del Quequén, un gaucho del siglo XIX, que se escondió allí para escapar de una partida policial y fue fuente de inspiración del cantautor León Gieco en su disco “Bandidos Rurales”.\r\n\r\nEn esta zona el mar y la barranca están en constante pugna, el mar queriendo desentrañar el pasado y la barranca preservando historia.\r\nEsta costa es elegida por aquellos visitantes que buscan la tranquilidad y el contacto con la naturaleza.\r\n\r\nEste es un excelente lugar para la práctica del surf (considerado uno de los mejores point), kayak y pesca, abundan las variedades de pescadillas, gatuzos, cazones, chuchos y pejerreyes.\r\nHacia el sur se extiende un paraíso, donde la naturaleza se presenta en todo su esplendor, y donde encontramos entre otras maravillas el imponente Médano Blanco.\r\n\r\nSe puede acceder con vehículo de tracción simple por un camino de tierra, con máxima precaución los días de lluvias o posteriores inmediatos a ellos; y, por camino costero únicamente en 4×4, en este recorrido se visualizan todos los matices que las playas necochenses presentan.\r\nEs menester mencionar que el Balneario no cuenta con servicios turísticos formales.', NULL, 1, '2026-06-24 22:52:32', NULL),
(25, 'Paraje Las Cascadas', '[\"/img/que-visitar/25/paraje-las-cascadas_2026-06-24_1.png\",\"/img/que-visitar/25/paraje-las-cascadas_2026-06-24_2.png\"]', 'Balneario natural de aguas templadas ubicado sobre el río Quequén aproximadamente a 12 kilómetros de la ciudad de Necochea, donde se concentran cascadas que en algunos sitios llegan a superar el metro de altura dependiendo del sector', 'Balneario natural de aguas templadas ubicado sobre el río Quequén aproximadamente a 12 kilómetros de la ciudad de Necochea, donde se concentran cascadas que en algunos sitios llegan a superar el metro de altura dependiendo del sector. Piletones naturales conjugados con espacios óptimos para practicar deportes náuticos (kayak, canotaje, rafting, remo).\r\n\r\nEl recorrido es en sí un atractivo, nos permite apreciar un imponente paisaje que la naturaleza nos brinda, observando el brillante serpenteo de sus aguas, los variados saltos sorteando irregulares piedras, el colorido de su forestación, los distintos ejemplares típicos de una rica fauna de aves de múltiples colores y tamaños, que se deslizan sobre la superficie del río o sobrevuelan su entorno y un marco ondulado de parcelas rurales.', '(02262) 15607455', 1, '2026-06-24 22:53:21', NULL),
(26, 'Las Grutas', '[\"/img/que-visitar/26/las-grutas_2026-06-24_1.png\"]', 'Paraje costero ubicado a 11 Kilómetros del centro de la ciudad, en este sitio es donde se comienza a visualizar un cambio en el paisaje costero con toscas que emergen en forma de acantilados de diferentes alturas y muchos de ellos con abundantes cavidades', 'Paraje costero ubicado a 11 Kilómetros del centro de la ciudad, en este sitio es donde se comienza a visualizar un cambio en el paisaje costero con toscas que emergen en forma de acantilados de diferentes alturas y muchos de ellos con abundantes cavidades. El suave declive y la arena fina pierden su protagonismo en esta costa de altura con presencia de conchillas y caracoles en la arena.\r\n\r\nEste paisaje surge en respuesta a la fuerza del mar que erosiona las rocas creando estas grutas lo que le determina su nombre.\r\nObservando las barrancas se visualizan pequeñas cuevas realizadas por grandes bandadas de loros barranqueros que la habitaban a fines del siglo XIX. Esta especie desapareció debido los cambios en la siembra del sector. Actualmente, estas cuevitas son aprovechadas por golondrinas europeas, que arriban a estas costas.\r\n\r\nLas Grutas es un lugar ideal para disfrutar de la playa, de la pesca y el surf.\r\nEn este sector se concentran la mayor parte de las cabañas y camping, muchos de ellos de dominio sindical. Se accede con vehículo de simple tracción y cuenta con bajadas para los vehículos 4×4. Cuenta también con servicios básicos para pasar el día en la zona.', NULL, 1, '2026-06-24 22:55:14', NULL),
(27, 'Médano Blanco', '[\"/img/que-visitar/27/medano-blanco_2026-06-24_1.png\"]', 'En este recorrido hacia el oeste, la línea costera dominante por la arboleda, comienza a mermar dejando lugar a una cadena de médanos única, también llamada como el “Sahara Necochense”, sitio imperdible para los amantes de las actividades 4×4.', 'En este recorrido hacia el oeste, la línea costera dominante por la arboleda, comienza a mermar dejando lugar a una cadena de médanos única, también llamada como el “Sahara Necochense”, sitio imperdible para los amantes de las actividades 4×4.\r\nLa imponencia de estos colosales médanos se empieza a visualizar a los 17 kilómetros donde emerge el Médano de la Mesa, cuyo nombre se debe a la extraña fisonomía que simula en su pico una plataforma similar a una mesa, es recomendable realizar este circuito con lugareños o con excursiones, para aprovechar al máximo la experiencia y no perderse en los caminos que cautivaron en el año 2012 a los corredores del internacionalmente famoso Rally Dakar.\r\n\r\nEn el kilómetro 42, se observa un pico de más de 100 metros de altura totalmente blanco, como si hubiese sido escenario de una gran nevada, en realidad es el efecto del brillo del sol en la cúspide del famoso “Médano Blanco”, de arenas doradas de textura fina y netamente movediza, que ostenta el título del médano más alto de la Costa Atlántica.\r\nEste médano es un punto panorámico natural por excelencia, desde él se observan playas vírgenes, pequeñas lagunas escondidas entre la llanura de la pampa húmeda e incluso un pequeño parque arbolado, reconocido como un punto energético, incluso sobre el sitio existen diversas leyendas sobre hechos sobrenaturales.\r\n\r\nEl sandboard, las cabalgatas, el trekking de aventura encuentran aquí un espacio natural único.', NULL, 1, '2026-06-24 22:56:15', NULL),
(28, 'Monumento a la Gesta de Malvinas', '[\"/img/que-visitar/28/monumento-a-la-gesta-de-malvinas_2026-06-24_1.png\"]', 'Este ícono ubicado en la ciudad de Quequén, sobre la Av. Almirante Brown a pocos metros de la Escollera Norte, fue inaugurado el 9 de octubre de 1999.', 'Este ícono ubicado en la ciudad de Quequén, sobre la Av. Almirante Brown a pocos metros de la Escollera Norte, fue inaugurado el 9 de octubre de 1999.\r\n\r\nLa obra del escultor Andrés Mirward, mide 35,70 metros de altura, y la imagen alude a los soldados caídos en acción durante el conflicto de las Islas Malvinas.\r\n\r\nSimboliza una gran bandera Argentina y la madre patria surgiendo de ella sosteniendo al soldado caído. Además posee una fuente perimetral, representando las lágrimas de madres y padres.\r\nSe halla orientado hacia la ubicación geográfica de dichas islas.', NULL, 1, '2026-06-24 22:56:48', NULL),
(29, 'Plaza Dardo Rocha Necochea', '[\"/img/que-visitar/29/plaza-dardo-rocha-necochea_2026-06-24_1.png\",\"/img/que-visitar/29/plaza-dardo-rocha-necochea_2026-06-24_2.png\"]', 'El microcentro de Necochea se ubica en la parte media de la ciudad, conocido como el casco histórico, distinguiéndose por la maravillosa plaza Dardo Rocha.', 'El microcentro de Necochea se ubica en la parte media de la ciudad, conocido como el casco histórico, distinguiéndose por la maravillosa plaza Dardo Rocha.\r\n\r\nPodemos encontrar los edificios históricos, destacándose las casas construidas en el año 1900 por los inmigrantes, la Parroquia Santa Maria del Carmen, el Colegio Nacional, el Palacio Municipal, el Cine Teatro París y el Correo Argentino, entre otros. Es el corazón financiero de la ciudad en el que se encuentran prestigiosos bancos de nivel nacional.\r\n\r\nTambién en el micro-centro se ubica un importante centro comercial, considerado un punto turístico debido a su variedad de negocios y que complementa la oferta turística que le brinda la Villa Díaz Vélez.\r\n\r\nAdemás, se puede disfrutar la gran variedad de establecimientos gastronómicos y bares.', NULL, 1, '2026-06-24 22:57:34', NULL),
(30, 'Puente Blanco', '[\"/img/que-visitar/30/puente-blanco_2026-06-24_1.png\",\"/img/que-visitar/30/puente-blanco_2026-06-24_2.png\"]', 'Por la ruta 86 a 60 kilómetros de la ciudad de Necochea, se encuentra este hermoso lugar envuelto en la tranquilidad y la belleza natural que ofrece el Río Quequén.', 'Por la ruta 86 a 60 kilómetros de la ciudad de Necochea, se encuentra este hermoso lugar envuelto en la tranquilidad y la belleza natural que ofrece el Río Quequén.\r\n\r\nEste histórico balneario, fue creado allá por la década del cuarenta, por iniciativa de José Werndl, que era miembro de la Sociedad de Fomento y amante de la vida al aire libre en general y del río en particular. Fue aquel visionario vecino el encargado de plantar y cuidar todo el monte, que hoy en día da sombra y forma parte del increíble paisaje del lugar.\r\n\r\nEl Balneario Puente Blanco, durante la temporada estival, cuenta con espacios para acampar, baños públicos, parrillas, salón comedor, servicio de cantina y guardavidas, todas cuestiones fundamentales para garantizar la seguridad y un día placentero. Durante todo el año se puede disfrutar del espacio natural y de la pesca.', '(02262) 15658728', 1, '2026-06-24 22:58:20', NULL),
(31, 'Puente Colgante Hipólito Yrigoyen', '[\"/img/que-visitar/31/puente-colgante-hipolito-yrigoyen_2026-06-24_1.png\",\"/img/que-visitar/31/puente-colgante-hipolito-yrigoyen_2026-06-24_2.png\"]', 'Este emblemático ícono se comenzó a construir en el año 1925, y se inauguró el 21 de julio de 1929 siendo un motivo de orgullo para todos los necochenses, ya que en ese momento solo existían 4 de su tipo en todo el mundo.', 'Este emblemático ícono se comenzó a construir en el año 1925, y se inauguró el 21 de julio de 1929 siendo un motivo de orgullo para todos los necochenses, ya que en ese momento solo existían 4 de su tipo en todo el mundo.\r\n\r\nEsta increíble obra es única por su estructura y características siendo una de las pocas que quedan en pie, además del gran despliegue que se hizo para su construcción.\r\nEl 17 de Febrero del 2006 se renovó y se re-inauguró tras un plan de preservación de obras de valor histórico.\r\n\r\nEn el año 1994 fue nombrado Patrimonio Provincial, en 1999, Patrimonio Municipal y en esa misma ordenanza se solicitó que sea monumento nacional.\r\n\r\nFue declarado Patrimonio Histórico Nacional, sin embargo, fue un largo camino que comenzó en 1994 y que finalmente el 9 de agosto de 2017, con la firma del Presidente de la Nación, se logra la tan ansiada declaración de esta postal y símbolo único de nuestro distrito.', NULL, 1, '2026-06-24 22:59:01', NULL);

